/**
 * JSON utilities for formatting, validation, and analysis
 */

export interface JsonStats {
  characterCount: number;
  keyCount: number;
  depth: number;
  hasArrays: boolean;
  hasObjects: boolean;
}

/**
 * Validates if a string is valid JSON
 */
export function validateJson(input: string): { valid: boolean; error?: string } {
  try {
    JSON.parse(input);
    return { valid: true };
  } catch (error) {
    return {
      valid: false,
      error: error instanceof Error ? error.message : 'Unknown error',
    };
  }
}

/**
 * Formats JSON with customizable indentation
 */
export function formatJson(input: string, indent: number = 2): string {
  const parsed = JSON.parse(input);
  return JSON.stringify(parsed, null, indent);
}

/**
 * Compacts JSON to a single line
 */
export function compactJson(input: string): string {
  const parsed = JSON.parse(input);
  return JSON.stringify(parsed);
}

/**
 * Analyzes JSON structure and returns statistics
 */
export function analyzeJson(input: string): JsonStats {
  const parsed = JSON.parse(input);
  const stringified = JSON.stringify(parsed);

  return {
    characterCount: stringified.length,
    keyCount: countKeys(parsed),
    depth: calculateDepth(parsed),
    hasArrays: hasArrays(parsed),
    hasObjects: hasObjects(parsed),
  };
}

function countKeys(obj: any): number {
  if (typeof obj !== 'object' || obj === null) return 0;

  let count = 0;
  if (Array.isArray(obj)) {
    for (const item of obj) {
      count += countKeys(item);
    }
  } else {
    count = Object.keys(obj).length;
    for (const value of Object.values(obj)) {
      count += countKeys(value);
    }
  }
  return count;
}

function calculateDepth(obj: any): number {
  if (typeof obj !== 'object' || obj === null) return 0;

  if (Array.isArray(obj)) {
    return obj.length === 0 ? 1 : 1 + Math.max(...obj.map(calculateDepth));
  }

  const values = Object.values(obj);
  return values.length === 0 ? 1 : 1 + Math.max(...values.map(calculateDepth));
}

function hasArrays(obj: any): boolean {
  if (typeof obj !== 'object' || obj === null) return false;
  if (Array.isArray(obj)) return true;

  for (const value of Object.values(obj)) {
    if (hasArrays(value)) return true;
  }
  return false;
}

function hasObjects(obj: any): boolean {
  if (typeof obj !== 'object' || obj === null) return false;
  if (Array.isArray(obj)) {
    return obj.some((item) => hasObjects(item));
  }
  return true;
}

